// UI reliability/polish layer for polls, reactions and provider fullscreen.
let uiState=null,uiMe=null,uiSocket=null,lastOwnVote=null;
const uiStyle=document.createElement('style');
uiStyle.textContent=`#reactions{z-index:30!important;right:22px!important;bottom:22px!important;display:flex;gap:8px;align-items:flex-end;filter:drop-shadow(0 8px 18px #000b)}#reactions span{display:inline-block;font-size:42px;will-change:transform,opacity;position:relative;z-index:31}#emoji button.reaction-pop{animation:reactionPop .34s ease}@keyframes reactionPop{0%{transform:scale(1)}45%{transform:scale(1.32) rotate(-8deg)}100%{transform:scale(1)}}.poll-card{border:1px solid #303038;border-radius:12px;background:#17171d;padding:14px;margin-bottom:12px}.poll-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:10px}.poll-head h3{margin:0;font-size:14px}.poll-meta{font-size:9px;color:#9696a2;white-space:nowrap}.poll-option{position:relative!important;overflow:hidden!important;background:#222229!important;border:1px solid #34343c!important;padding:12px 13px!important;margin:7px 0!important;display:grid!important;grid-template-columns:minmax(0,1fr) auto!important;gap:12px!important;align-items:center!important}.poll-option:hover{border-color:#6d7656!important}.poll-option.selected{border-color:#d3f56b!important;box-shadow:0 0 0 1px #d3f56b44 inset}.poll-option:disabled{opacity:.8!important;cursor:default!important}.poll-option .poll-label,.poll-option .poll-stat{position:relative;z-index:2}.poll-option .poll-stat{font-size:10px;color:#bfc7a6}.poll-bar{position:absolute;left:0;top:0;bottom:0;background:#d3f56b16;z-index:1;transition:width .28s ease}.poll-selected-tag{font-size:8px;color:#d3f56b;margin-left:6px}.poll-footer{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:10px;color:#858590;font-size:9px}.poll-close{padding:7px 9px!important;font-size:9px!important}.screen:fullscreen{width:100vw!important;height:100vh!important;max-width:none!important;aspect-ratio:auto!important;border-radius:0!important;background:#000!important}.screen:fullscreen #reactions{right:4vw!important;bottom:8vh!important}`;
document.head.appendChild(uiStyle);
function uiToast(text){const t=document.getElementById('toast');if(!t)return;t.textContent=text;t.style.display='block';setTimeout(()=>{if(t.textContent===text)t.style.display='none'},3000)}
function escUi(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function sendUi(type,data={}){if(uiSocket?.readyState===1)uiSocket.send(JSON.stringify({type,...data,actionId:crypto.randomUUID()}))}
function renderPollPolish(){const node=document.getElementById('pollContent');if(!node||!uiState)return;const p=uiState.poll;if(!p){node.innerHTML='<div class="muted">What should we watch next? Let the room decide.</div>';lastOwnVote=null;return}const choices=Object.values(p.votes||{}),counts=p.options.map((_,i)=>choices.filter(v=>v===i).length),total=choices.length,own=(p.votes||{})[uiMe],closed=!!p.closed;node.innerHTML=`<div class="poll-card"><div class="poll-head"><h3>${escUi(p.question)}</h3><span class="poll-meta">${total} vote${total===1?'':'s'}${closed?' · CLOSED':''}</span></div>`+p.options.map((option,i)=>{const pct=total?Math.round(counts[i]*100/total):0,selected=own===i;return `<button class="poll-option${selected?' selected':''}" data-vote="${i}" ${closed?'disabled':''}><span class="poll-bar" style="width:${pct}%"></span><span class="poll-label">${escUi(option)}${selected?'<span class="poll-selected-tag">YOUR VOTE</span>':''}</span><span class="poll-stat">${counts[i]} · ${pct}%</span></button>`}).join('')+`<div class="poll-footer"><span>${closed?'Final result':'Tap an option to vote · you can change your vote'}</span>${uiState.host===uiMe&&!closed?'<button class="poll-close" data-ui-close-poll>Close poll</button>':''}</div></div>`;if(own!==undefined&&own!==lastOwnVote){uiToast(lastOwnVote===null?'Vote recorded ✓':'Vote updated ✓');lastOwnVote=own}}
function pulseReaction(emoji){const b=[...document.querySelectorAll('#emoji button')].find(x=>x.textContent.trim()===String(emoji).trim());if(!b)return;b.classList.remove('reaction-pop');void b.offsetWidth;b.classList.add('reaction-pop')}
const PreviousWebSocket=window.WebSocket;
window.WebSocket=class FrameUiWebSocket extends PreviousWebSocket{constructor(...args){super(...args);uiSocket=this;this.addEventListener('message',event=>{try{const data=JSON.parse(event.data);if(data.type==='welcome')uiMe=data.id;if(data.type==='state'){uiState=data;setTimeout(renderPollPolish,0)}if(data.type==='reaction'){pulseReaction(data.emoji);const layer=document.getElementById('reactions');if(layer)layer.style.zIndex='30'}}catch{}})}};
document.getElementById('pollForm')?.addEventListener('submit',()=>setTimeout(()=>{const q=document.getElementById('question'),o=document.getElementById('options');if(q)q.value='';if(o)o.value=''},80));
document.addEventListener('click',event=>{const close=event.target.closest('[data-ui-close-poll]');if(close){event.preventDefault();event.stopPropagation();sendUi('closePoll');uiToast('Poll closed.');return}const emoji=event.target.closest('#emoji button');if(emoji)pulseReaction(emoji.textContent)},true);
function patchYouTubePlayer(){if(!window.YT?.Player||window.YT.Player.__frameFullscreenPatched)return false;const NativePlayer=window.YT.Player;function FramePlayer(element,options={}){return new NativePlayer(element,{...options,playerVars:{...(options.playerVars||{}),fs:0}})}try{Object.setPrototypeOf(FramePlayer,NativePlayer)}catch{}FramePlayer.prototype=NativePlayer.prototype;FramePlayer.__frameFullscreenPatched=true;window.YT.Player=FramePlayer;return true}
patchYouTubePlayer();const priorReady=window.onYouTubeIframeAPIReady;window.onYouTubeIframeAPIReady=()=>{try{priorReady?.()}finally{patchYouTubePlayer()}};let ytPatchAttempts=0;const ytPatchTimer=setInterval(()=>{ytPatchAttempts++;if(patchYouTubePlayer()||ytPatchAttempts>100)clearInterval(ytPatchTimer)},100);
